def icon(name):
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + ICONS[name] + '</svg>'

NAV = {
 'en': ['Guard Family','Classroom','Browser Guard','Help','Join the closed beta','Menu','Skip to content','Tools for learning. Room for family life.','Products','Resources','Privacy','Blog','Contact','Home','Open dashboard','Closed beta · Free to try with feedback and testimonials.'],
 'ja': ['Guard Family','教室向け','ブラウザ保護','ヘルプ','ベータに参加','メニュー','本文へ移動','学びを支えるツール。家族の時間を大切に。','製品','案内','プライバシー','ブログ','お問い合わせ','ホーム','ダッシュボードを開く','クローズドベータ · フィードバックと体験談を共有して無料で試用。'],
 'zh': ['Guard Family','课堂工具','浏览器防护','帮助','参加封闭测试','菜单','跳至正文','帮助学习，留出更多家庭时间。','产品','资源','隐私','博客','联系','首页','打开控制面板','封闭测试 · 免费试用，分享反馈和使用心得。'],
 'vi': ['Guard Family','Lớp học','Bảo vệ trình duyệt','Trợ giúp','Tham gia beta kín','Menu','Chuyển đến nội dung','Công cụ học tập. Thêm thời gian cho gia đình.','Sản phẩm','Tài nguyên','Quyền riêng tư','Blog','Liên hệ','Trang chủ','Mở bảng điều khiển','Beta kín · Dùng thử miễn phí, chia sẻ phản hồi và trải nghiệm.'],
}

def button(text, href, primary=False):
    return f'<a class="btn btn-{"primary" if primary else "secondary"}" href="{E(href, quote=True)}">{E(text)}</a>'

def card(title, text, bullets=(), href=None, label=None, eyebrow=None, symbol=None):
    parts = ['<article class="card">']
    if symbol: parts.append('<div class="card-icon">' + icon(symbol) + '</div>')
    if eyebrow: parts.append('<span class="eyebrow">' + E(eyebrow) + '</span>')
    parts += ['<h3>' + E(title) + '</h3>', '<p>' + E(text) + '</p>']
    if bullets: parts.append('<ul>' + ''.join('<li>' + E(x) + '</li>' for x in bullets) + '</ul>')
    if href: parts.append(f'<a class="text-link" href="{E(href, quote=True)}">{E(label or "Learn more")}</a>')
    return ''.join(parts) + '</article>'

def section(title, content, description='', eyebrow='', id=None):
    return '<section class="section"' + (f' id="{E(id)}"' if id else '') + '><div class="section-title"><div>' + (f'<span class="eyebrow">{E(eyebrow)}</span>' if eyebrow else '') + f'<h2>{E(title)}</h2></div>' + (f'<p>{E(description)}</p>' if description else '') + '</div>' + content + '</section>'

def hero(title, intro, eyebrow='', actions=(), tags=(), diagram=None):
    text = (f'<span class="eyebrow">{E(eyebrow)}</span>' if eyebrow else '') + '<h1>' + E(title) + '</h1><p class="lead">' + E(intro) + '</p>'
    if actions: text += '<div class="actions">' + ''.join(actions) + '</div>'
    if tags: text += '<div class="platforms">' + ''.join('<span class="tag">' + E(x) + '</span>' for x in tags) + '</div>'
    return '<section class="hero' + ('' if diagram else ' simple') + '">' + ('<div class="hero-grid"><div>' + text + '</div>' + diagram + '</div>' if diagram else text) + '</section>'

def notice(text):
    return '<div class="notice"><p>' + E(text) + '</p></div>'

def faq(items):
    return ''.join('<details class="faq"><summary>' + E(q) + '</summary><p>' + E(a) + '</p></details>' for q,a in items)

def cta(title='Help shape the next Layers.', text='', lang='en'):
    return '<section class="cta-band"><div><h2>' + E(title) + '</h2>' + ('<p>' + E(text) + '</p>' if text else '') + '<p>' + beta_copy(lang) + '</p></div>' + button(NAV[lang][4], 'contact.html?topic=access', True) + '</section>'

def relationship(lang='en'):
    # Keep the product explorable: this mount renders the React device mockups.
    # The detailed walkthrough below shares the same sample state.
    return '<div data-guard-demo="compact"><noscript><p>Enable JavaScript to explore the interactive app preview.</p></noscript></div>'


def shell(filename, title, description, content, lang='en', editorial=False, noindex=False):
    path = Path(filename)
    prefix = '../' if len(path.parts) > 1 else ''
    n = NAV[lang]
    def url(route):
        # Localized pages link to a translated route when it exists, otherwise to the English page.
        base, sep, fragment = route.partition('#')
        base, query_sep, query = base.partition('?')
        if lang != 'en' and base in LOCALIZED:
            result = base
        else:
            result = prefix + base
        return result + ('?' + query if query_sep else '') + ('#' + fragment if sep else '')
    routes = [('guard-pro.html',n[0]),('teacher.html',n[1]),('guard.html',n[2]),('support.html',n[3])]
    current = path.name
    interactive = current in {'index.html', 'guard-pro.html'} and not editorial
    if interactive:
        walkthrough = '<section class="interactive-section" id="demo" aria-label="Interactive Layers Guard walkthrough"><div data-guard-demo="full"><noscript><p>Enable JavaScript to try the app with sample data.</p></noscript></div></section>'
        invitation = '<aside class="notice"><p><strong>' + E(BETA[lang][0]) + '</strong> ' + beta_copy(lang) + '</p></aside>'
        content = content.replace('</section>', '</section>' + invitation + walkthrough, 1)
    demo_assets = (f'<link rel="stylesheet" href="{prefix}assets/product-demo.css"><script src="{prefix}assets/product-demo.js" defer></script>' if interactive else '')
    if current == 'teacher.html' and not editorial:
        demo_assets += f'<link rel="stylesheet" href="{prefix}assets/teacher-demo.css"><script src="{prefix}assets/teacher-demo.js" defer></script>'
    if current == 'guard.html' and not editorial:
        demo_assets += f'<link rel="stylesheet" href="{prefix}assets/browser-guard-demo.css"><script src="{prefix}assets/browser-guard-demo.js" defer></script>'
    navigation = ''.join(f'<a href="{url(route)}"' + (' aria-current="page"' if current==route else '') + '>' + E(label) + '</a>' for route,label in routes)
    brand = '<a class="site-brand" href="' + url('index.html') + '">' + icon('layers') + '<span>Layers</span></a>'
    canonical = 'https://www.thelayersapp.com/' + (str(path).replace('\\','/') if path.name!='index.html' else (lang+'/' if lang!='en' else ''))
    alts = ''
    if current in LOCALIZED:
        for code in NAV:
            route = (code+'/' if code!='en' else '') + ('' if current=='index.html' else current)
            alts += f'<link rel="alternate" hreflang="{code}" href="https://www.thelayersapp.com/{route}">\n'
        alts += '<link rel="alternate" hreflang="x-default" href="https://www.thelayersapp.com/' + ('' if current=='index.html' else current) + '">'
    lang_links = ''
    if current in LOCALIZED:
        for code,label in [('en','English'),('ja','日本語'),('zh','中文'),('vi','Tiếng Việt')]:
            target = prefix + (code+'/' if code!='en' else '') + current
            lang_links += '<a href="' + target + '" lang="' + code + '" hreflang="' + code + '"' + (' aria-current="page"' if code==lang else '') + '>' + label + '</a>'
    products = [('guard-pro.html','Guard Family'),('guard-desktop.html','Guard Desktop · Windows'),('guard-mobile.html','Guard Mobile · Android'),('dashboard.html',n[14]),('teacher.html','Layers Teacher'),('student.html','Layers Student'),('guard.html',n[2])]
    resources = [('get.html',n[4]),('support.html',n[3]),('blog/index.html',n[11]),('contact.html',n[12]),('privacy.html',n[10])]
    def links(items): return ''.join('<a href="' + url(route) + '">' + E(label) + '</a>' for route,label in items)
    html = f'''<!DOCTYPE html>
<html lang="{lang}">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{E(title)} — Layers</title><meta name="description" content="{E(description, quote=True)}">
<meta name="theme-color" content="#142c38"><link rel="canonical" href="{canonical}">
<meta property="og:title" content="{E(title, quote=True)} — Layers"><meta property="og:description" content="{E(description, quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website">
{alts}
{'<meta name="robots" content="noindex,follow">' if noindex else ''}
<link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="{prefix}assets/site.css"><script src="{prefix}assets/site.js" defer></script>
{demo_assets}
<noscript><style>.menu-toggle{{display:none!important}}</style></noscript>
</head>
<body class="site{' editorial' if editorial else ''}">
<a class="skip-link" href="#main">{n[6]}</a>
<header class="site-header"><div class="container header-row">{brand}
<button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">{n[5]}</button>
<nav class="site-nav" id="site-nav" aria-label="{'Main navigation' if lang=='en' else n[8]}">{navigation}<a class="nav-contact" href="{url('contact.html?topic=access')}">{n[4]}</a></nav>
<a class="btn btn-primary header-action" href="{url('contact.html?topic=access')}">{n[4]}</a>
</div></header>
<main id="main" class="container">{content}</main>
<footer class="site-footer"><div class="container"><div class="footer-grid"><div class="footer-brand-block">{brand}<p>{n[7]}</p><p>{n[15]}<br><a href="mailto:contact@thelayersapp.com">contact@thelayersapp.com</a></p></div><div class="footer-group"><strong>{n[8]}</strong>{links(products)}</div><div class="footer-group"><strong>{n[9]}</strong>{links(resources)}</div></div><div class="footer-bottom"><span>© 2026 Layers</span><nav class="language-links" aria-label="Language">{lang_links}</nav></div></div></footer>
</body></html>
'''
    target = ROOT / filename
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(html, encoding='utf-8')

LOCALIZED = {'index.html','get.html','guard-pro.html','support.html','soho.html','layersinstall.html'}

