def guard_family():
    content = hero('Their devices. Your family’s rhythm.', 'Set everyday boundaries for Windows PCs and Android devices from the Layers Guard web dashboard or Android Controller. Review time spent, manage rules, and respond when your child asks for a little more time.', 'Guard Family', [button('Join the closed beta','contact.html?topic=guard',True),button('Open dashboard','dashboard.html')], ['Windows child app','Android child app','Browser parent dashboard'], relationship())
    content += section('A calmer way to manage screen time.', '<div class="cards">' + card('Time that fits the day','Set a daily device allowance, individual app limits, bedtime, and weekday/weekend schedules.',symbol='clock') + card('Rules for apps and websites','Maintain blocked lists, set allowed time windows, pause internet access, or send an immediate device lock.',symbol='shield') + card('A conversation, not a dead end','Children can request more time or access to an app or website. Parents can approve or deny from their controls.',symbol='book') + card('Today, Trends, Controls','See recent device status, screen-time totals and app usage, then adjust the selected device’s rules.',symbol='globe') + card('Content alerts','Review potentially harmful content detected on supported surfaces. Scanning is a useful signal and can miss content or flag it incorrectly.',symbol='shield') + card('A PIN for parent actions','Parent-only actions use a PIN. Device diagnostics help identify missing permissions, startup problems, or a connection that needs attention.',symbol='check') + '</div>')
    content += section('One parent view. Two child platforms.', '<div class="table-wrap"><table><caption class="small">Choose the app for the device’s role.</caption><thead><tr><th scope="col">Tool</th><th scope="col">Where it runs</th><th scope="col">What it does</th></tr></thead><tbody><tr><td>Web dashboard</td><td>A modern browser</td><td>Parent account, pairing, activity, rules and requests</td></tr><tr><td>Guard Controller</td><td>Parent’s Android device</td><td>Companion parent interface with Today, Trends and Controls</td></tr><tr><td>Guard Desktop</td><td>Child’s Windows 10/11 PC</td><td>Device controls, app/site restrictions and usage reporting</td></tr><tr><td>Guard Mobile</td><td>Child’s Android device</td><td>Permissions-based app/site controls and usage reporting</td></tr></tbody></table></div>' + notice('Each device must be paired and configured. Controls depend on the child app running with the required permissions. Remote changes need a connection; saved schedules and rules are applied locally. Protection status should be checked in the dashboard.'),id='platforms')
    content += section('Set up the child device first.', '<div class="cards">' + card('Install the child app','Ask us for the current Windows or Android build. Complete the parent-led permission and startup setup.',eyebrow='01') + card('Pair with your parent account','Open the dashboard or Android Controller and add the child’s device using its pairing code. Pairing codes expire, so use the code currently shown.',eyebrow='02') + card('Check status and set rules','Choose the device, verify its reported protection status, then set time limits, bedtime and restrictions.',eyebrow='03') + '</div><div class="actions">' + button('Windows setup details','guard-desktop.html') + button('Android setup details','guard-mobile.html') + '</div>',id='setup')
    content += section('Questions before you start?', faq([('Is Guard Family the same as the free extension?','No. Guard Family uses paired Windows and Android child apps with a parent dashboard. The free browser Guard extension keeps its settings in the browser and is managed locally.'),('Can I manage everything from a browser?','The web dashboard is a parent controller. Your child’s Windows or Android device still needs the corresponding app, pairing, and permissions.'),('Does it support Mac or iPhone child devices?','Mac apps are discontinued, and there is no iPhone/iPad child app in the current lineup. A parent can use a compatible browser on these devices to open the web dashboard.'),('Can protection be bypassed?','Device settings, administrator access, disabled permissions, network loss and other factors can reduce protection. Check the reported status and follow the setup guidance; Layers does not promise that any device is impossible to bypass.'),('How do I get access?','We’re inviting participants to a free closed beta in exchange for honest feedback and testimonials. Email contact@thelayersapp.com with the apps and devices you’d like to try. Existing licence keys can still be entered where the app asks for them.')])) + cta('Find a setup that fits your family.','Tell us the Windows and Android devices you want to manage. We’ll help you choose the right apps.')
    return content

